"""Concatenated Words — word break against the *other* words.

Processing words shortest-first means every candidate piece is already in the
dictionary set when a longer word is tested.

Time: O(n * L^2)   Space: O(n * L)
"""
from typing import List


class Solution:
    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
        shorter = set()
        out = []

        def composable(word: str) -> bool:
            if not word:
                return False
            reachable = [True] + [False] * len(word)
            for end in range(1, len(word) + 1):
                for start in range(end):
                    if reachable[start] and word[start:end] in shorter:
                        reachable[end] = True
                        break
            return reachable[-1]

        for word in sorted(words, key=len):
            if composable(word):
                out.append(word)
            shorter.add(word)
        return out
